#!/usr/bin/env python3
"""Write the Markdown tables of the Figure 4 replication (results/summary.md).

usage: report_fig4.py   (after parse_logs.py and compare_fig4.py)

Reads results/stats/*.tsv, results/fig4.csv, results/fig4.partial.csv, fig4/comparison.csv and
fig4/sieve_ranks.csv; the totals of the paper's Table 1 are constants below.
"""
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parent.parent
ORDER = ["SIEVE", "ARC", "TinyLFU", "TwoQ", "LIRS", "LHD", "CACHEUS", "Hyperbolic", "CLOCK",
         "LRU", "B-LRU"]
DS = {"metaKV": "Meta KV", "metaCDN": "Meta CDN", "tencentPhoto": "Tencent Photo", "wiki": "Wiki CDN"}
TABLE1 = {"metaKV": (5, 1644, 82), "metaCDN": (3, 231, 76), "tencentPhoto": (2, 5650, 1038),
          "wiki": (3, 2863, 56)}  # paper Table 1: traces, requests (M), objects (M)
DS_OF = {"meta_": "metaCDN", "kvcache": "metaKV", "tencent": "tencentPhoto", "wiki": "wiki"}


def md(df):
    cols = list(df.columns)
    out = ["| " + " | ".join(map(str, cols)) + " |", "|" + "---|" * len(cols)]
    out += ["| " + " | ".join(map(str, r)) + " |" for r in df.itertuples(index=False)]
    return "\n".join(out)


def main():
    stats = pd.concat(pd.read_csv(f, sep="\t", header=None) for f in sorted((ROOT / "results/stats").glob("*.tsv"))
                      if f.name != "header.tsv")
    stats.columns = ["trace", "file_bytes", "requests", "objects", "wss_scaling", "wss_obj", "small", "large"]
    stats["trace"] = stats.trace.str.replace(".oracleGeneral.zst", "", regex=False)
    stats["dataset"] = [next(v for k, v in DS_OF.items() if t.startswith(k)) for t in stats.trace]
    cmp_ = pd.read_csv(ROOT / "fig4/comparison.csv")
    rk = pd.read_csv(ROOT / "fig4/sieve_ranks.csv")
    ours = pd.read_csv(ROOT / "results/fig4.csv")
    run_of = {(t, "a" if z == "large" else "b"): r for t, z, r in
              ours[["trace", "size", "run"]].drop_duplicates().itertuples(index=False)}
    tidx = rk.drop_duplicates("trace").set_index("trace").trace_idx

    out = ["# Figure 4 replication: tables", "",
           "Generated by `scripts/report_fig4.py` from `results/` and `fig4/`.", ""]

    # 1. traces vs Table 1
    out += ["## Traces", "",
            "Requests and objects as cachesim reads them (requests of size 0 skipped). `paper dot` = which",
            "of the paper's dots (1 = most opaque) the trace matched. Cache sizes are what cachesim",
            "computes from 0.1% and 10% of the footprint.", ""]
    rows = []
    for _, s in stats.sort_values(["dataset", "trace"]).iterrows():
        rows.append(dict(dataset=DS[s.dataset], trace=s.trace, **{"requests (M)": f"{s.requests / 1e6:,.1f}",
                    "objects (M)": f"{s.objects / 1e6:,.1f}", "small cache": f"{s.small:,}",
                    "large cache": f"{s.large:,}", "paper dot": tidx.get(s.trace, "")}))
    out += [md(pd.DataFrame(rows)), ""]
    tot = stats.groupby("dataset")[["requests", "objects"]].sum()
    rows = [dict(dataset=DS[d], traces=f"{(stats.dataset == d).sum()} / {t1[0]}",
                 **{"requests (M) ours / Table 1": f"{tot.loc[d, 'requests'] / 1e6:,.0f} / {t1[1]:,}",
                    "objects (M) ours / Table 1": f"{tot.loc[d, 'objects'] / 1e6:,.0f} / {t1[2]:,}"})
            for d, t1 in TABLE1.items() if d in tot.index]
    out += ["Totals against the paper's Table 1:", "", md(pd.DataFrame(rows)), ""]

    # 2. SIEVE per trace
    out += ["## SIEVE on every trace", "",
            "Rank among the 11 algorithms (1 = best) and miss ratio reduction from FIFO, paper vs replication.", ""]
    s = cmp_[cmp_.algo == "SIEVE"].merge(rk, on=["panel", "dataset", "trace", "trace_idx"])
    s = s.sort_values(["panel", "dataset", "trace_idx"])
    rows = [dict(panel=r.panel, dataset=DS[r.dataset], trace=r.trace, **{
        "paper dot": r.trace_idx, "SIEVE paper": f"{r.reduction_paper:.4f}", "SIEVE ours": f"{r.reduction:.4f}",
        "rank paper": r.sieve_rank_paper, "rank ours": r.sieve_rank, "best paper": r.best_paper,
        "best ours": r.best, "trace version": "10% sample" if run_of[(r.trace, r.panel)] != r.trace
        else "whole"}) for r in s.itertuples()]
    out += [md(pd.DataFrame(rows)), ""]
    n = len(s)
    same_rank = int((s.sieve_rank == s.sieve_rank_paper).sum())
    same_best = int((s.best == s.best_paper).sum())
    out += [f"SIEVE's rank equals the paper's in **{same_rank} of {n}** trace × panel cases; the best "
            f"algorithm is the same in **{same_best} of {n}**.", ""]

    # 3. per algorithm difference
    out += ["## Difference from the paper per algorithm", "",
            "Absolute difference (replication − paper) of the miss ratio reduction, over all trace × panel points.", ""]
    cmp_["ad"] = cmp_["diff"].abs()
    g = cmp_.groupby("algo").ad.agg(["mean", "max", "count"]).reindex(ORDER)
    rows = [dict(algorithm=a, **{"mean abs. diff": f"{r['mean']:.4f}", "max abs. diff": f"{r['max']:.4f}",
                                 "points": int(r["count"])}) for a, r in g.iterrows()]
    out += [md(pd.DataFrame(rows)), ""]
    big = cmp_.sort_values("ad", ascending=False).head(10)
    rows = [dict(panel=r.panel, dataset=DS[r.dataset], trace=r.trace, algorithm=r.algo,
                 paper=f"{r.reduction_paper:.4f}", ours=f"{r.reduction:.4f}", diff=f"{r.diff:+.4f}")
            for r in big.itertuples()]
    out += ["The 10 largest differences:", "", md(pd.DataFrame(rows)), ""]

    # 4. Tencent sampling validation
    part = ROOT / "results/fig4.partial.csv"
    if part.exists():
        pv = pd.read_csv(part)
        pv = pv[pv.run.str.endswith(".whole_large")]
        if len(pv):
            sm = ours[(ours.run.str.endswith(".s10")) & (ours["size"] == "large")]
            m = pv.merge(sm, on=["trace", "algo"], suffixes=("_whole", "_s10"))
            rows = [dict(trace=r.trace, algorithm=r.algo, **{
                "miss ratio whole": f"{r.miss_ratio_whole:.4f}", "miss ratio 10%": f"{r.miss_ratio_s10:.4f}",
                "reduction whole": f"{r.reduction_whole:.4f}", "reduction 10%": f"{r.reduction_s10:.4f}",
                "diff": f"{r.reduction_s10 - r.reduction_whole:+.4f}"}) for r in m.itertuples()]
            out += ["## Tencent large cache: 10% sample vs whole trace", "",
                    "The algorithms whose large cache (53 M objects) fits in memory, run on the whole trace and",
                    "on the 10% spatial sample used for panel (a).", "", md(pd.DataFrame(rows)), ""]

    (ROOT / "results/summary.md").write_text("\n".join(out))
    print("\n".join(out))


if __name__ == "__main__":
    main()
